import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ChartAnimationProps = Record<string, any>;

const ChartAnimation: React.FC<ChartAnimationProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "THE REEL DEAL",
  subtitle = "Days in the week where movie watchers are the highest",
  barValues = [80, 35, 60, 45, 75, 65, 95],
  barColors = [
    "#80e0e0", // Sunday
    "#6cd6d6", // Monday
    "#59cccd", // Tuesday
    "#46c2c4", // Wednesday
    "#33b8ba", // Thursday
    "#20aeb1", // Friday
    "#0d7da8"  // Saturday (darker blue/teal shift)
  ],
  days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
  emptyPillColor = "#FFFFFF",
  textColor = "#FFFFFF",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Layout Constants
  const MAX_VALUE = 100;
  const PILLS_PER_BAR = 20; // Each pill represents 5 units
  const VALUE_PER_PILL = MAX_VALUE / PILLS_PER_BAR;
  
  // Stagger config
  const BAR_STAGGER = 5; // frames between bars starting
  const PILL_STAGGER = 2; // frames between pills in a bar

  // Helper to get animation values for a specific pill
  const getPillAnimation = (barIndex: number, pillIndex: number) => {
    // Determine start frame for this specific pill
    // Pills animate from bottom (0) to top
    const startFrame = (barIndex * BAR_STAGGER) + (pillIndex * PILL_STAGGER) + 10; // +10 for initial delay
    
    // Spring for color fill
    const progress = spring({
      frame: frame - startFrame,
      fps,
      config: {
        damping: 12,
        stiffness: 100,
        mass: 0.5,
      },
      durationInFrames: 20, 
    });

    const opacity = interpolate(progress, [0, 1], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    return { opacity };
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Inter, sans-serif",
        color: textColor,
        padding: "5%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-start",
      }}
    >
      {/* Header Section */}
      <div style={{ 
        marginBottom: "4rem", 
      }}>
        <h1 style={{ 
          fontSize: "2.5rem", 
          fontWeight: 700, 
          margin: "0 0 0.5rem 0",
          textTransform: "uppercase",
          letterSpacing: "0.05em"
        }}>
          {title}
        </h1>
        <p style={{ 
          fontSize: "1.2rem", 
          margin: 0, 
          opacity: 0.8,
          fontWeight: 400 
        }}>
          {subtitle}
        </p>
      </div>

      {/* Chart Container */}
      <div style={{
        flex: 1,
        display: "flex",
        flexDirection: "row",
        position: "relative",
        alignItems: "flex-end", // Align bars to bottom
        paddingLeft: "3rem", // Space for Y-axis
        paddingBottom: "2rem", // Space for X-axis
      }}>
        
        {/* Grid Lines (Horizontal) */}
        <div style={{
          position: "absolute",
          top: 0,
          left: "3rem",
          right: 0,
          bottom: "2rem",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          zIndex: 0,
        }}>
          {[100, 80, 60, 40, 20, 0].map((val) => (
            <div key={val} style={{ 
              width: "100%", 
              height: 1, 
              backgroundColor: "rgba(255,255,255,0.1)",
              position: "relative" 
            }}>
              <span style={{
                position: "absolute",
                left: "-3rem",
                top: "-0.5em",
                fontSize: "1rem",
                width: "2.5rem",
                textAlign: "right",
                opacity: 0.6,
                fontWeight: 600
              }}>
                {val}
              </span>
            </div>
          ))}
        </div>

        {/* Bars Container */}
        <div style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "flex-end",
          zIndex: 1,
        }}>
          {days.map((day, barIndex) => {
            const value = barValues[barIndex] ?? 0;
            const barColor = barColors[barIndex % barColors.length];
            
            // Calculate filled pills
            const filledCount = Math.ceil(value / VALUE_PER_PILL);

            return (
              <div
                key={day}
                style={{
                  flex: 1,
                  height: "100%",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "flex-end",
                  alignItems: "center",
                  position: "relative",
                }}
              >
                {/* Pills Stack */}
                <div style={{
                  display: "flex",
                  flexDirection: "column-reverse", // Bottom is index 0
                  gap: "4px", // Gap between pills
                  width: "40%", // Width of the bar relative to column width
                  height: "100%",
                }}>
                  {Array.from({ length: PILLS_PER_BAR }).map((_, i) => {
                    const isFilled = i < filledCount;
                    const animation = getPillAnimation(barIndex, i);
                    
                    return (
                      <div
                        key={i}
                        style={{
                          width: "100%",
                          flex: "1 1 0%", // Distribute height evenly
                          minHeight: 0,
                          position: "relative", // Ensure children absolute positioning works
                        }}
                      >
                        {/* Base "Grayed Out" Layer (Always Visible) */}
                        <div style={{
                          position: "absolute",
                          inset: 0,
                          backgroundColor: emptyPillColor,
                          opacity: 0.2, // Dimmed state
                          borderRadius: "2px",
                        }} />

                        {/* Active "Lit Up" Layer (Fades In) */}
                        {isFilled && (
                          <div style={{
                            position: "absolute",
                            inset: 0,
                            backgroundColor: barColor,
                            opacity: animation.opacity, // Animates 0 -> 1
                            borderRadius: "2px",
                            boxShadow: `0 0 8px ${barColor}40`,
                          }} />
                        )}
                      </div>
                    );
                  })}
                </div>

                {/* X-Axis Label */}
                <div style={{
                  position: "absolute",
                  bottom: "-2.5rem",
                  textAlign: "center",
                  width: "100%",
                  fontSize: "1rem",
                  fontWeight: 500,
                  opacity: 1,
                }}>
                  {day}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChartAnimation;